#!/usr/bin/env node

/**
 * sign-license.mjs
 *
 * Signs a license string using RSA-SHA256 with the private key generated by
 * generate-license-keys.mjs.
 *
 * The resulting signature is stored in LicenseActivation.signature and
 * verified at runtime by ModuleSubscriptionGuard.verifyOfflineLicense().
 *
 * Usage:
 *   node scripts/sign-license.mjs --license "PRO-ENT-2026-XXXX-YYYY" --private-key scripts/.license-keys/private.pem
 *   node scripts/sign-license.mjs --license "PRO-ENT-2026-XXXX-YYYY" --private-key scripts/.license-keys/private.pem --output scripts/.license-keys/signature.txt
 *
 * The output is a hex-encoded signature string suitable for insertion into
 * the LicenseActivation.signature column.
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createSign } from 'node:crypto';
import path from 'node:path';

function parseArgs() {
  const args = process.argv.slice(2);
  const result: Record<string, string> = {};
  for (const arg of args) {
    if (arg.startsWith('--')) {
      const [key, value] = arg.slice(2).split('=');
      result[key] = value || 'true';
    }
  }
  return result;
}

const opts = parseArgs();
const licenseKey = opts.license;
const privateKeyPath = opts['private-key'] || path.resolve(process.cwd(), 'scripts', '.license-keys', 'private.pem');
const outputPath = opts.output;

if (!licenseKey) {
  console.error('Usage: node scripts/sign-license.mjs --license <license-key> --private-key <path-to-private.pem>');
  process.exit(1);
}

if (!existsSync(privateKeyPath)) {
  console.error(`Private key not found: ${privateKeyPath}`);
  console.error('Run generate-license-keys.mjs first.');
  process.exit(1);
}

const privateKey = readFileSync(privateKeyPath, 'utf-8');

const sign = createSign('SHA256');
sign.update(licenseKey);
const signature = sign.sign(privateKey, 'hex');

console.log(`[sign-license] License: ${licenseKey}`);
console.log(`[sign-license] Signature: ${signature}`);

if (outputPath) {
  writeFileSync(outputPath, signature);
  console.log(`[sign-license] Signature written to: ${outputPath}`);
}

console.log('');
console.log('SQL INSERT example:');
console.log(`  INSERT INTO "LicenseActivation" ("companyId", "licenseKey", "signature", "isValid", "registeredModules")`);
console.log(`  VALUES ('<company-uuid>', '${licenseKey}', '${signature}', true, '["double-entry","inventory"]');`);
